    "tool_call": {
      "type": "object",
      "required": [
        "tool_name",
        "input_params",
        "purpose",
        "instruction"
      ],
      "properties": {
        "tool_name": {
          "enum": [
            "use_aws",
            "use_pipeline"
          ]
        },
        "input_params": {
          "type": "object"
        },
        "purpose": {
          "type": "string",
          "description": "Natural language explanation of what this step accomplishes in the mitigation plan"
        },
        "instruction": {
          "type": "string",
          "description": "Specific instructions for the plan executor on what values to capture, verify, or actions to take"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "tool_name": {
                "const": "use_aws"
              }
            }
          },
          "then": {
            "properties": {
              "input_params": {
                "$ref": "#/definitions/aws_params"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "tool_name": {
                "const": "use_pipeline"
              }
            }
          },
          "then": {
            "properties": {
