                "required": [
                  "source_deployment"
                ],
                "properties": {
                  "source_deployment": {
                    "$ref": "#/definitions/deployment"
                  },
                  "issue_start_time": {
                    "type": "string"
                  }
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "operation": {
                "const": "pre_validate_rollback_target"
              }
            }
          },
          "then": {
            "properties": {
              "parameters": {
                "type": "object",
                "required": [
                  "target_deployment"
                ],
                "properties": {
                  "target_deployment": {
                    "$ref": "#/definitions/deployment"
                  }
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "operation": {
                "const": "rollback_deployment"
              }
            }
          },
          "then": {
            "properties": {
              "parameters": {
                "type": "object",
                "required": [
                  "source_deployment",
                  "target_deployment"
                ],
                "properties": {
                  "source_deployment": {
                    "$ref": "#/definitions/deployment"
                  },
                  "target_deployment": {
                    "$ref": "#/definitions/deployment"
                  }
                }
              }
            }
          }
        }
      ]
    },
    "deployment": {
      "type": "object",
      "required": [
        "workflow_name",
        "workflow_run_id",
